def aux(s, t):
	n = len(s)
	lpr = 0
	for i in range(n):
		if s[i] != t[i]:
			break
		lpr += 1
	lsf = 0
	for i in range(n - 1, -1, -1):
		if s[i] != t[i]:
			break
		lsf += 1
	if lpr == n:
		return 2
	return (s[lpr:n - lsf - 1] == t[lpr + 1:n - lsf]) + (t[lpr:n - lsf - 1] == s[lpr + 1:n - lsf])
